/* Fűtéstuning custom Home Assistant Lovelace card, v0.1.2 */
const DATA={
 buffer:"sensor.elite_thr316d_sonoff_1002bdc9e4_temperature",
 alert:"binary_sensor.hideg_puffer_futesi_igeny_van",
 circuits:[
 ["Pince","sensor.wifi_rs_beepitett_szelep_1_homerseklet","number.wifi_rs_futeskor_1_szelep_beallitott_hom","switch.pince_szivattyu_mini_d"],
 ["Padlófűtés","sensor.wifi_rs_beepitett_szelep_2_homerseklet","number.wifi_rs_futeskor_2_szelep_beallitott_hom","switch.padlo_szivattyu_mini_d"],
 ["Radiátor","sensor.wifi_rs_beepitett_szelep_3_homerseklet","number.wifi_rs_futeskor_3_szelep_beallitott_hom","switch.radiator_szivattyu_mini_d"]
 ],
 rooms:[
 ["Emelet","Gréta háló","sensor.greta_radiator_temperature","climate.greta_radiator"],
 ["Emelet","Emeleti fürdő","sensor.emeleti_furdo_homero_temperature",null],
 ["Emelet","Flóra háló","sensor.flora_homero_temperature",null],
 ["Földszint","Szülői háló",null,null],
 ["Földszint","Dolgozó","sensor.dolgozo_homero_temperature","climate.dolgozo_radiator"],
 ["Földszint","Földszinti fürdő","sensor.foldszinti_furdo_radiator_temperature","climate.foldszinti_furdo_radiator"],
 ["Földszint","Hanna háló","sensor.hanna_homero_temperature",null],
 ["Földszint","Nappali / konyha / étkező","sensor.nappali_homero_temperature",null],
 ["Földszint","Garázs","sensor.garazs_homero_temperature",null],
 ["Pince","Lenti garázs",null,null]
 ]};
const STYLE=`:host{display:block;color:#e9f4fb;font:500 15px system-ui}*{box-sizing:border-box}.root{background:linear-gradient(135deg,#091521,#13293a);padding:clamp(14px,2vw,27px);min-height:520px;border-radius:20px}.heading{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:22px}h1{font-size:30px;margin:0}h2{font-size:20px;margin:20px 0 12px}.sub{color:#a1becd;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:15px}.tile{background:linear-gradient(150deg,#1b3448,#172737);border:1px solid #34546a;border-radius:17px;padding:17px;min-width:0}.tile.hot{background:linear-gradient(145deg,#64313d,#2d2737);border-color:#c76864;box-shadow:inset 0 0 24px #d9534f18}.interactive{cursor:pointer}.interactive:hover{border-color:#7ad7ed}.name{font-weight:700}.value{font-size:clamp(22px,2.6vw,35px);font-weight:800;margin:9px 0;white-space:nowrap;line-height:1.18;font-variant-numeric:tabular-nums}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;min-width:0}.row>div{min-width:0}.roomtemp{font-size:clamp(26px,2.6vw,36px);line-height:1.2;font-variant-numeric:tabular-nums;white-space:nowrap;margin:10px 0 4px;font-weight:800}.requested{font-size:17px;white-space:nowrap;font-variant-numeric:tabular-nums}.roomcard{min-height:135px}.roomcard .name{font-size:15px;min-height:20px}.level{border-top:1px solid #345269;margin-top:17px}.tag{font-size:12px;color:#a6c4d5}.warn{color:#ffb49e}.diagram{overflow:auto;border:1px solid #36566c;border-radius:15px;background:#0c2030}.diagram svg{display:block;width:100%;min-width:780px}.pipe-hot{stroke:#ed9e7c;stroke-width:10;fill:none}.pipe-cold{stroke:#62a9d4;stroke-width:10;fill:none}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-top:15px}button{font:inherit;color:#eaf5ff;background:#2b4b61;border:1px solid #61869d;border-radius:9px;padding:9px 15px;cursor:pointer}.overlay{position:fixed;inset:0;background:#02070bdc;display:grid;place-items:center;z-index:100;padding:20px}.modal{background:#152d40;border:1px solid #54758a;border-radius:20px;padding:24px;width:min(470px,100%)}.stepper{display:flex;gap:16px;justify-content:center;align-items:center;margin:24px 0}.stepper strong{font-size:34px}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:510px){.grid,.stats{grid-template-columns:1fr}}`;
class FutestuningCard extends HTMLElement {
 setConfig(cfg){this.cfg={view:"home",...cfg};if(!["home","plant","rooms"].includes(this.cfg.view))throw Error("Invalid view");if(!this.shadowRoot){this.attachShadow({mode:"open"});this.shadowRoot.innerHTML="<style>"+STYLE+"</style><div id='root'></div>"}this.render()}
 set hass(v){this._hass=v;this.render()}
 get hass(){return this._hass}
 s(id){return this._hass?.states?.[id]}
 on(id){return this.s(id)?.state==="on"}
 demand(id){const s=this.s(id)?.state;return s==="on"?"Hőigény":s==="off"?"Nincs hőigény":"Hőigény ismeretlen"}
 pump(i){const c=DATA.circuits[i],s=this.s(c[3])?.state;
 if(s==="off")return {active:false,label:"Becsült szivattyú: áll"};
 if(i===0)return {active:false,label:"Szivattyúállapot ismeretlen"};
 const raw=this.s(DATA.buffer)?.state,t=Number(raw),limit=i===1?30:35;
 if(s!=="on"||raw==null||raw===""||!Number.isFinite(t)||t<=-100)return {active:false,label:"Szivattyúállapot ismeretlen"};
 return {active:t>limit,label:t>limit?"Becsült szivattyú: működik":"Becsült szivattyú: áll"};
 }
 fmt(id){const v=this.s(id)?.state,n=Number(v);return v!==undefined&&v!=="unavailable"&&v!=="unknown"&&Number.isFinite(n)&&n>-100?n.toFixed(1).replace(".",",")+" °C":"—"}
 target(id){const raw=this.s(id)?.attributes?.temperature,n=Number(raw);return raw!=null&&Number.isFinite(n)?n.toFixed(1).replace(".",",")+" °C":"—"}
 heading(){return this.cfg.view==="home"?"Főoldal":this.cfg.view==="plant"?"Kazánház":"Helyiségek"}
 render(){if(!this.shadowRoot||!this._hass)return;const r=this.shadowRoot.getElementById("root");r.innerHTML=`<div class="root"><div class="heading"><div><h1>♨ Fűtés · ${this.heading()}</h1><div class="sub">TECH · SONOFF · Home Assistant</div></div><span class="tag">Fűtéstuning</span></div>${this.cfg.view==="home"?this.home():this.cfg.view==="plant"?this.plant():this.rooms()}</div>`;r.querySelectorAll("[data-target]").forEach(e=>e.addEventListener("click",()=>this.editTarget(+e.dataset.target)));r.querySelectorAll("[data-climate]").forEach(e=>e.addEventListener("click",()=>this.dispatchEvent(new CustomEvent("hass-more-info",{detail:{entityId:e.dataset.climate},bubbles:true,composed:true}))))}
 home(){const active=DATA.circuits.filter(c=>this.on(c[3])).length;return `<div class="stats"><div class="tile"><div class="tag">PUFFER · TH ELITE</div><div class="value">${this.fmt(DATA.buffer)}</div></div><div class="tile"><div class="tag">HŐIGÉNYES KÖRÖK</div><div class="value">${active}/3</div><div class="tag">Nem szivattyúállapot</div></div><div class="tile"><div class="tag">HMV</div><div class="value">—</div><div class="tag">Nincs bekötött érzékelő</div></div><div class="tile ${this.on(DATA.alert)?"hot":""}"><div class="tag">PUFFER FELÜGYELET</div><div class="value">${this.on(DATA.alert)?"⚠ Hideg":"—"}</div></div></div><div class="grid">${DATA.circuits.map((c,i)=>this.circuit(c,i)).join("")}<div class="tile"><div class="name">HMV</div><div class="value">—</div><div class="sub">Külön kör · hőmérő még nincs</div></div><div class="tile"><div class="name">Hozzáépítés</div><div class="value">2 alkör</div><div class="sub">Computherm autonóm vezérlés</div></div></div>`}
 circuit(c,i){const hot=this.on(c[3]);return `<div class="tile interactive ${hot?"hot":""}" data-target="${i}"><div class="name">${c[0]}</div><div class="value">${this.fmt(c[1])}</div><div class="sub">Cél: ${this.fmt(c[2])}</div><div class="tag ${hot?"warn":""}">${this.demand(c[3])} · célérték állítható</div><div class="tag">${this.pump(i).label}</div></div>`}
 rooms(){return ["Emelet","Földszint","Pince"].map(level=>`<section class="level"><h2>${level}</h2><div class="grid">${DATA.rooms.filter(r=>r[0]===level).map(r=>{let climate=this.s(r[3]),heat=climate?.attributes?.hvac_action==="heating",actual=r[2]?this.fmt(r[2]):Number.isFinite(Number(climate?.attributes?.current_temperature))?Number(climate.attributes.current_temperature).toFixed(1)+" °C":"—";return `<div class="tile roomcard ${heat?"hot":""} ${r[3]?"interactive":""}" ${r[3]?`data-climate="${r[3]}"`:""}><div class="row"><span class="name">${r[1]}</span><span>${r[3]?"›":""}</span></div><div class="row"><div><div class="roomtemp">${actual}</div><div class="tag">Mért</div></div><div style="text-align:right"><b class="requested">${r[3]?this.target(r[3]):"—"}</b><div class="tag">Kért</div></div></div><div class="tag ${heat?"warn":""}">${heat?"● Fűt":climate?"Állapot nem igazolt":"Állapotadat nincs"}</div></div>`}).join("")}</div></section>`).join("")}
 plant(){const cx=[520,805,1090];const routes=DATA.circuits.map((c,i)=>`<path class="pipe-hot" d="M${cx[i]} 177 V244"/><path class="pipe-cold" d="M${cx[i]+30} 435 V520"/><rect x="${cx[i]-110}" y="244" width="220" height="190" rx="16" fill="#20394e" stroke="#4a738d"/><text x="${cx[i]-93}" y="276" fill="white" font-size="20">${c[0]}</text><text x="${cx[i]-93}" y="326" fill="#eaf6ff" font-size="26">${this.fmt(c[1])}</text><text x="${cx[i]-93}" y="356" fill="#b0d0de" font-size="17">Cél: ${this.fmt(c[2])}</text><text x="${cx[i]-93}" y="393" fill="${this.on(c[3])?"#fcae9a":"#b0d0de"}" font-size="16">${this.demand(c[3])}</text><text x="${cx[i]-93}" y="418" fill="#b0d0de" font-size="13">${this.pump(i).label}</text>`).join("");return `<div class="diagram"><svg viewBox="0 0 1340 595" xmlns="http://www.w3.org/2000/svg"><rect x="25" y="130" width="180" height="245" rx="16" fill="#233e50" stroke="#4c708a"/><text x="45" y="180" font-size="21" fill="white">ATTACK</text><text x="45" y="210" font-size="16" fill="#b5d0dc">PROFI PID</text><rect x="250" y="130" width="155" height="245" rx="42" fill="#28495f" stroke="#76a4bc"/><text x="273" y="186" font-size="22" fill="white">Puffer</text><text x="263" y="232" font-size="25" fill="white">${this.fmt(DATA.buffer)}</text><path class="pipe-hot" d="M205 158 H250 M405 177 H1220"/><path class="pipe-cold" d="M1220 520 H405 V355"/>${routes}<rect x="440" y="20" width="795" height="85" rx="15" fill="#1c394f" stroke="#4a738d"/><text x="465" y="57" fill="white" font-size="25">TECH EU-i-3 PLUS OT</text><text x="465" y="85" fill="#b0d0de" font-size="16">Három kör · valós előremenő hőmérsékletek</text><text x="440" y="560" fill="#a8c8d8" font-size="18">HMV: mérés hiányzik · Hozzáépítés: önálló vezérlés</text></svg></div><div class="sub" style="margin-top:12px">Meleg előremenő: narancs · visszatérő: kék. Becsült szivattyújelzés: MINI-D hőigény és TH Elite &gt;30 °C (padló), &gt;35 °C (radiátor). Nem igazolt forgás. Pince: nincs becslési küszöb megadva.</div><div class="controls">${DATA.circuits.map((c,i)=>`<button data-target="${i}">${c[0]} · célhőmérséklet</button>`).join("")}</div>`}
 editTarget(i){const c=DATA.circuits[i],state=this.s(c[2]);if(!state)return;let val=Number(state.state),min=Number(state.attributes?.min??10),max=Number(state.attributes?.max??80),step=Number(state.attributes?.step??1);if(!Number.isFinite(val))return;const overlay=document.createElement("div");overlay.className="overlay";overlay.innerHTML=`<div class="modal"><div class="row"><h2>${c[0]} célhőmérséklet</h2><button id="close">✕</button></div><div class="sub">Csak a TECH célértékét módosítja.</div><div class="stepper"><button id="minus">−</button><strong id="temp"></strong><button id="plus">+</button></div><button id="save" style="width:100%">Mentés</button></div>`;this.shadowRoot.append(overlay);const close=()=>overlay.remove(),refresh=()=>overlay.querySelector("#temp").textContent=val.toFixed(1).replace(".",",")+" °C";refresh();overlay.querySelector("#close").onclick=close;overlay.querySelector("#minus").onclick=()=>{val=Math.max(min,+(val-step).toFixed(2));refresh()};overlay.querySelector("#plus").onclick=()=>{val=Math.min(max,+(val+step).toFixed(2));refresh()};overlay.querySelector("#save").onclick=async()=>{let b=overlay.querySelector("#save");b.disabled=true;try{await this._hass.callService("number","set_value",{entity_id:c[2],value:val});close()}catch(e){b.disabled=false;b.textContent="Hiba – újrapróbálás"}}}
 getCardSize(){return 8}
}
if(!customElements.get("futestuning-card"))customElements.define("futestuning-card",FutestuningCard);
window.customCards=window.customCards||[];
window.customCards.push({type:"futestuning-card",name:"Fűtéstuning",description:"Háromnézetes fűtés áttekintő"});
